 static List<string> results=new List<string>();
 static void Check(bool value,string name){results.Add((value?"PASS ":"FAIL ")+name);if(!value)throw new Exception(name);}
 static string Record(string type,string payload){return "{\"timestamp\":\""+DateTimeOffset.UtcNow.ToString("o")+"\",\"type\":\""+type+"\",\"payload\":"+payload+"}\n";}
 static bool RespectsPaintClip(Control control){using(control)using(var canvas=new Bitmap(180,100))using(var g=Graphics.FromImage(canvas)){control.Size=new Size(140,38);g.Clear(Color.Magenta);g.TranslateTransform(20,20);g.SetClip(new Rectangle(0,0,24,24));var args=new PaintEventArgs(g,new Rectangle(0,0,24,24));foreach(string method in new[]{"OnPaintBackground","OnPaint"})typeof(Control).GetMethod(method,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(control,new object[]{args});for(int y=0;y<canvas.Height;y++)for(int x=0;x<canvas.Width;x++)if((x<20||x>=44||y<20||y>=44)&&canvas.GetPixel(x,y).ToArgb()!=Color.Magenta.ToArgb())return false;return true;}}
 static bool NoSiblingOverlap(Control parent){var children=parent.Controls.Cast<Control>().Where(c=>c.Visible).ToArray();for(int i=0;i<children.Length;i++){for(int j=i+1;j<children.Length;j++)if(children[i].Bounds.IntersectsWith(children[j].Bounds))return false;if(!NoSiblingOverlap(children[i]))return false;}return true;}
 static Control FindText(Control root,string text){if(root.Text==text)return root;foreach(Control child in root.Controls){var found=FindText(child,text);if(found!=null)return found;}return null;}
 static void TestSchedules(string folder){
  var start=new DateTime(2026,10,26,8,30,0);var once=new ScheduleEntry{Title="单次事件",Repeat="once",Start=start,Notes="备注"};
  Check(once.Next(start.AddSeconds(-1))==start&&once.Next(start)==null&&once.Latest(start)==start,"One-time schedule is due exactly at its selected time");
  var daily=new ScheduleEntry{Title="每日",Repeat="daily",Start=start};Check(daily.Next(start)==start.AddDays(1)&&daily.Latest(start.AddDays(2).AddMinutes(-1))==start.AddDays(1),"Daily schedules use local wall time and respect the start date");
  var weekly=new ScheduleEntry{Title="每周",Repeat="weekly",Start=start,WeeklyDays=new[]{1,3,5}};
  Check(weekly.Next(start)==start.AddDays(2)&&weekly.Latest(start.AddDays(3))==start.AddDays(2),"Weekly schedules support several selected weekdays");
  weekly.WeeklyDays=new[]{5};Check(weekly.Next(start.AddDays(-1))==start.AddDays(4)&&weekly.Latest(start.AddDays(2))==null,"Weekly schedules do not invent an occurrence on an unselected start weekday");
  var monthly=new ScheduleEntry{Title="月末",Repeat="monthly",Start=new DateTime(2027,1,31,9,0,0)};
  Check(monthly.Next(new DateTime(2027,2,1))==new DateTime(2027,2,28,9,0,0)&&monthly.Next(new DateTime(2027,3,1))==new DateTime(2027,3,31,9,0,0),"A monthly 31st reminder uses February's last day then returns to March 31");
  var yearly=new ScheduleEntry{Title="闰年",Repeat="yearly",Start=new DateTime(2024,2,29,10,0,0)};
  Check(yearly.Next(new DateTime(2025,1,1))==new DateTime(2025,2,28,10,0,0)&&yearly.Next(new DateTime(2028,1,1))==new DateTime(2028,2,29,10,0,0),"A yearly February 29 reminder handles ordinary and leap years");
  var book=new ScheduleBook();book.Items.Add(once.Copy());bool changed;Check(book.CollectDue(start.AddSeconds(-1),out changed).Count==0&&!changed,"Schedules do not notify early");
  var due=book.CollectDue(start,out changed);Check(due.Count==1&&changed&&!book.Items[0].Enabled&&due[0].Entry.Notes=="备注","Due one-time schedules retain notes and become completed");
  Store.Save("schedule-test.json",book);book=Store.Load<ScheduleBook>("schedule-test.json");Check(book.CollectDue(start.AddMinutes(1),out changed).Count==0&&!changed,"A restart cannot repeat an already handled reminder");
  book=new ScheduleBook();book.Items.Add(daily.Copy());Check(book.CollectDue(start.AddDays(3).AddHours(1),out changed).Count==1&&book.CollectDue(start.AddDays(3).AddHours(2),out changed).Count==0,"Wake-up delivers only the latest missed recurrence, once");
  Check(book.CollectDue(start.AddDays(2),out changed).Count==0,"Moving the clock backward cannot duplicate a handled occurrence");
  book=new ScheduleBook();var disabled=daily.Copy();disabled.Enabled=false;book.Items.Add(disabled);Check(book.CollectDue(start.AddDays(1),out changed).Count==0&&!changed&&disabled.Next(start)==null,"Disabled schedules neither notify nor show an active next time");
  book=new ScheduleBook();book.Items.Add(once.Copy());Check(book.CollectDue(start.AddDays(3),out changed).Count==0&&changed,"One-time reminders older than the catch-up window are retired without a stale alert");
  var roundtrip=Json.Serializer().Deserialize<ScheduleEntry>(Json.Encode(yearly));Check(roundtrip.LocalStart==yearly.LocalStart&&roundtrip.Start==yearly.Start,"Schedule dates round-trip as local calendar values without UTC conversion");
  bool invalid=false;try{new ScheduleEntry{Title="",Start=start}.Validate(start.AddDays(-1));}catch(ArgumentException){invalid=true;}Check(invalid,"Schedule validation rejects missing event names");
  invalid=false;try{once.Validate(start);}catch(ArgumentException){invalid=true;}Check(invalid,"A new one-time reminder must use a future time");
  invalid=false;try{new ScheduleEntry{Title="每周",Repeat="weekly",Start=start,WeeklyDays=new int[0]}.Validate(start.AddDays(-1));}catch(ArgumentException){invalid=true;}Check(invalid,"A weekly reminder requires at least one weekday");
  Check(UtilityCatalog.Items.Length==4&&UtilityCatalog.Items.Select(x=>x.Icon).Distinct().Count()==4&&UtilityCatalog.Items.All(x=>LineIcons.HasToolSymbol(x.Icon)),"Every utility has its own icon definition");
  foreach(var tool in UtilityCatalog.Items)using(var icon=LineIcons.Tool(tool.Icon,128)){icon.Save(Path.Combine(folder,"icon-"+tool.Id+".png"),ImageFormat.Png);Check(icon.GetPixel(64,64).A>0,"White-and-purple rounded utility icon renders: "+tool.Name);}
  using(var circle=new Bitmap(64,64))using(var square=new Bitmap(64,64)){using(var g=Graphics.FromImage(circle)){g.Clear(Color.Transparent);g.FillEllipse(Brushes.DeepPink,2,2,60,60);}using(var g=Graphics.FromImage(square))g.Clear(Color.DarkBlue);Check(LineIcons.IsCircular(circle)&&!LineIcons.IsCircular(square),"Game icon shape detection distinguishes circular and square originals");using(var output=LineIcons.OutlineGame(circle))output.Save(Path.Combine(folder,"icon-circle-original.png"),ImageFormat.Png);using(var output=LineIcons.OutlineGame(square))output.Save(Path.Combine(folder,"icon-square-original.png"),ImageFormat.Png);}
